begin;
insert into auth.users(id,email,email_confirmed_at) values('ec010101-0101-4101-8101-010101010101','event-admin@invalid.example',now());
insert into forge_redesign_test.staff_members(email,user_id,role) values('event-admin@invalid.example','ec010101-0101-4101-8101-010101010101','admin');
do $$declare p uuid:=gen_random_uuid();j uuid;later_job uuid;lease uuid:=gen_random_uuid();later_lease uuid:=gen_random_uuid();e jsonb;blocked boolean;stamp timestamptz:=now();begin
 if has_table_privilege('anon','forge_redesign_test.notification_provider_events','select') or has_function_privilege('authenticated','public.forge_notification_provider_event(text,uuid,text,timestamptz)','execute') or has_table_privilege('service_role','forge_redesign_test.notification_provider_events','update') then raise exception 'Provider evidence publicly editable';end if;
 -- Event can precede the worker's provider-ID receipt.
 perform public.forge_notification_provider_event('rollback-delivered',p,'email.delivered',stamp);
 perform public.forge_notification_provider_event('rollback-delivered',p,'email.delivered',stamp);
 if (select count(*) from forge_redesign_test.notification_provider_events where event_id='rollback-delivered')<>1 then raise exception 'Duplicate webhook persisted twice';end if;
 blocked:=false;begin perform public.forge_notification_provider_event('rollback-delivered',p,'email.bounced',stamp);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Conflicting replay accepted';end if;
 j:=public.forge_proposal_submit('{"name":"Synthetic receipt","school":"Rollback school","email":"events@invalid.example"}');
 later_job:=public.forge_proposal_submit('{"name":"Synthetic receipt two","school":"Rollback school two","email":"events@invalid.example"}');
 update forge_redesign_test.proposal_notification_outbox set status='sending',first_attempt_at=now()-interval '1 minute',lease_token=lease,leased_until=now()+interval '5 minutes' where id=j;
 update forge_redesign_test.proposal_notification_outbox set status='sending',first_attempt_at=now(),lease_token=later_lease,leased_until=now()+interval '5 minutes' where id=later_job;
 e:=public.forge_notification_send_guard('proposal',later_job,'events@invalid.example');if e->>'unresolved' is distinct from 'false' then raise exception 'Never-sent older claim held recipient';end if;
 e:=public.forge_notification_begin_send('proposal',later_job,later_lease);if e->>'unresolved' is distinct from 'false' then raise exception 'First reservation blocked';end if;
 e:=public.forge_notification_begin_send('proposal',j,lease);if e->>'unresolved' is distinct from 'true' then raise exception 'Older prechecked job bypassed a newer reservation';end if;
 if (select acceptance_uncertain from forge_redesign_test.proposal_notification_outbox where id=j) then raise exception 'Held job acquired uncertainty without sending';end if;
 perform public.forge_notification_send_rejected('proposal',later_job,later_lease,false);
 e:=public.forge_notification_begin_send('proposal',j,lease);if e->>'priorUncertain' is distinct from 'false' then raise exception 'New send incorrectly ambiguous';end if;
 if not public.forge_notification_send_rejected('proposal',j,lease,false) then raise exception 'Rejection not recorded';end if;
 e:=public.forge_notification_send_guard('proposal',later_job,'events@invalid.example');if e->>'unresolved' is distinct from 'false' then raise exception 'Definite first rejection held recipient';end if;
 perform public.forge_notification_begin_send('proposal',j,lease);
 e:=public.forge_notification_begin_send('proposal',j,lease);if e->>'priorUncertain' is distinct from 'true' then raise exception 'Earlier uncertain attempt lost';end if;
 perform public.forge_notification_send_rejected('proposal',j,lease,true);
 perform public.forge_notification_provider_event('rollback-orphan-bounce',p,'email.bounced',stamp);
 e:=public.forge_notification_send_guard('proposal',later_job,'events@invalid.example');
 if e->>'unresolved' is distinct from 'true' then raise exception 'Distinct message passed unresolved acceptance';end if;
 e:=public.forge_notification_send_guard('proposal',j,'events@invalid.example');
 if e->>'unresolved' is distinct from 'false' then raise exception 'Original idempotent recovery blocked';end if;
 update forge_redesign_test.proposal_notification_outbox set status='sent',provider_id=p::text,sent_at=now() where id=j;
 e:=public.forge_notification_send_guard('proposal',later_job,'events@invalid.example');
 if e->>'suppressed' is distinct from 'true' then raise exception 'Recovered bounce did not suppress distinct message';end if;
 -- Use a second clean provider for the independent ordering assertions below.
 p:=gen_random_uuid();update forge_redesign_test.proposal_notification_outbox set provider_id=p::text where id=j;
 perform public.forge_notification_provider_event('rollback-clean-delivered',p,'email.delivered',stamp);
 perform public.forge_notification_provider_event('rollback-delay',p,'email.delivery_delayed',stamp-interval '1 hour');
 if public.forge_notification_delivery_summary(p::text)->>'status'<>'delivered' then raise exception 'Reordered delay overwrote delivery';end if;
 if public.forge_notification_recipient_blocked('events@invalid.example') then raise exception 'Delivery suppressed healthy recipient';end if;
 perform public.forge_notification_provider_event('rollback-bounce',p,'email.bounced',stamp);
 if not public.forge_notification_recipient_blocked('EVENTS@invalid.example') then raise exception 'Bounced recipient not suppressed';end if;
 if public.forge_notification_recipient_blocked('someone-else@invalid.example') then raise exception 'Foreign recipient suppressed';end if;
 perform public.forge_notification_provider_event('rollback-later-delivered',p,'email.delivered',stamp+interval '1 minute');
 if public.forge_notification_delivery_summary(p::text)->>'status'<>'bounced' then raise exception 'Later event erased bounce evidence';end if;
 perform public.forge_notification_provider_event('rollback-complaint',p,'email.complained',stamp);
 if public.forge_notification_delivery_summary(p::text)->>'status'<>'complained' then raise exception 'Complaint ignored';end if;
 e:=public.forge_notification_staff_action('ec010101-0101-4101-8101-010101010101','event-admin@invalid.example','list','{"queue":"proposal"}');
 if not exists(select 1 from jsonb_array_elements(e->'items') x where x->>'id'=j::text and x#>>'{delivery,status}'='complained') then raise exception 'Staff did not see delivery evidence';end if;
 e:=public.forge_notification_staff_action('ec010101-0101-4101-8101-010101010101','not-staff@invalid.example','list','{"queue":"proposal"}');if e->>'forbidden' is distinct from 'true' then raise exception 'Staff identity bypass';end if;
 blocked:=false;begin update forge_redesign_test.notification_provider_events set event_type='email.delivered' where event_id='rollback-complaint';exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Historical evidence mutable';end if;
end $$;
select 'PASS: signatures persisted separately, duplicate/reorder safety, private staff status, recipient suppression and immutable evidence; rolled back' as outcome;
rollback;
